const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/*
<thinking>
1. Search strategy: Use MODIS Aqua MYD11A1 (daily, ~1:30 pm local overpass) for Paris on 2024-08-06, region = 15 km buffer around city center.
2. Masking strategy: Apply QC_Day mask: bits 0-1 == 00 (good LST) and bits 6-7 <= 01 (LST error <= 2K). No cloud masking needed beyond QC.
3. Logic for valid vs null/error: If collection size == 0 => C1. If valid pixel count == 0 => C2. If stats are null/NaN or physically implausible (e.g., max < -50 or > 80 C) => C3. Otherwise compare max LST to 32 C to decide A/B.
</thinking>
*/

async function runAnalysis() {
  const getInfo = (obj) =>
    new Promise((resolve, reject) =>
      obj.getInfo((res) => resolve(res), (err) => reject(err))
    );

  // 1. Geometry & Time Definitions
  const paris = ee.Geometry.Point([2.3522, 48.8566]);
  const region = paris.buffer(15000).bounds(); // ~Paris metro
  const start = '2024-08-06';
  const end = '2024-08-07';
  const tz = 'Europe/Paris';
  console.log('Location: Paris (48.8566, 2.3522), Buffer: 15 km');
  console.log('Date: 2024-08-06 Local (Europe/Paris)');

  // 2. Data Acquisition & Check
  let col = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(start, end)
    .filterBounds(region);
  let n = await getInfo(col.size());
  console.log(`MYD11A1 images: ${n}`);
  if (!n || n === 0) {
    console.log('No Aqua MYD11A1 images found on this date/region.');
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    return;
  }

  let img = ee.Image(col.first());
  const imgLocalTime = await getInfo(
    ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm', tz)
  );
  console.log(`Image local time: ${imgLocalTime}`);

  // 3. Processing (QC mask and counts)
  const qa = img.select('QC_Day');
  const good = qa.bitwiseAnd(3).eq(0); // bits 0-1 == 00 (good quality)
  const errOK = qa.rightShift(6).bitwiseAnd(3).lte(1); // bits 6-7 <= 01 (LST error <= 2K)
  const lstK = img.select('LST_Day_1km').updateMask(good.and(errOK));
  const lstC = lstK.multiply(0.02).subtract(273.15).rename('LSTc');

  const totalCount = await getInfo(
    img.select('LST_Day_1km').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
    }).get('LST_Day_1km')
  );

  const validCount = await getInfo(
    lstC.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
    }).get('LSTc')
  );

  const validPct = totalCount ? (100.0 * (validCount || 0) / totalCount) : 0;
  console.log(`Pixels (1km): total=${totalCount || 0}, valid=${validCount || 0} (${validPct.toFixed(1)}%)`);

  if (!validCount || validCount === 0) {
    console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
    return;
  }

  // 4. Calculation (summary stats)
  const reducers = ee.Reducer.mean()
    .combine({reducer2: ee.Reducer.percentile([90]), sharedInputs: true})
    .combine({reducer2: ee.Reducer.max(), sharedInputs: true});
  const stats = lstC.reduceRegion({
    reducer: reducers,
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  });
  const meanC = await getInfo(stats.get('LSTc_mean'));
  const p90C = await getInfo(stats.get('LSTc_p90'));
  const maxC = await getInfo(stats.get('LSTc_max'));

  if (
    meanC === null || p90C === null || maxC === null ||
    isNaN(meanC) || isNaN(p90C) || isNaN(maxC) ||
    maxC < -50 || maxC > 80
  ) {
    console.log('C3: Calculation Failure (Result is `None`, `NaN`, or invalid).');
    return;
  }

  console.log(`LST (°C): mean=${meanC.toFixed(1)}, p90=${p90C.toFixed(1)}, max=${maxC.toFixed(1)}`);

  // 5. Final Answer
  const exceeded = maxC > 32.0;
  console.log(`Threshold 32°C exceeded? ${exceeded ? 'Yes' : 'No'}`);
  if (exceeded) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.log(`Error: ${e.message}`);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
  }
}

initEE();
